/**
 * Base64-encoded banner images for JKT48 member types (Love, Dream, Passion).
 * These are used as oshi card banners based on the member's type.
 */

export const OSHI_BANNER_LOVE =
	'data:image/jpeg;base64,';

export const OSHI_BANNER_DREAM =
	'data:image/jpeg;base64,';

export const OSHI_BANNER_PASSION =
	'data:image/jpeg;base64,';

export const OSHI_BANNER_DEFAULT =
	'data:image/png;base64,';

/**
 * Returns the appropriate oshi banner image based on member type.
 * Members with type Love, Dream, or Passion get their team banner.
 * All other types (JKT48, Trainee, etc.) get the default JKT48 Fight banner.
 */
export function getOshiBanner(memberType?: string): string {
	switch (memberType?.toUpperCase()) {
		case 'LOVE':
			return OSHI_BANNER_LOVE;
		case 'DREAM':
			return OSHI_BANNER_DREAM;
		case 'PASSION':
			return OSHI_BANNER_PASSION;
		default:
			return OSHI_BANNER_DEFAULT;
	}
}
